// theme-fixes.js
const fs=require('fs');const path=require('path');const{execSync}=require('child_process');
const files={"frontend/src/app/dashboard/discounts/page.tsx":"\"use client\";\n\nimport { useState, useEffect } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { api } from \"../../../lib/api\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport toast from \"react-hot-toast\";\nimport {\n  Plus, Tag, Zap, BarChart2, Repeat2, Clock, Layers, Package,\n  Trash2, ToggleLeft, ToggleRight, X, ChevronRight, TrendingUp,\n  Gift, Timer, Star, AlertCircle,\n} from \"lucide-react\";\n\n// ── Types ────────────────────────────────────────────────────────────────────\ntype DiscountType = \"PERCENTAGE\" | \"FIXED\" | \"FREE_SHIPPING\" | \"BOGO\" | \"TIERED\" | \"FLASH_SALE\" | \"BUNDLE\";\ntype ValueType    = \"PERCENTAGE\" | \"FIXED_AMOUNT\" | \"NEW_PRICE\" | \"FREE\";\n\ninterface TierRow { minQty: number; discount: number; }\n\ninterface DiscountForm {\n  name:           string;\n  description:    string;\n  type:           DiscountType;\n  valueType:      ValueType;\n  value:          number;\n  maxDiscount:    number;\n  minOrderValue:  number;\n  minQuantity:    number;\n  isAutomatic:    boolean;\n  stackable:      boolean;\n  priority:       number;\n  freeShipping:   boolean;\n  firstOrderOnly: boolean;\n  maxUses:        number;\n  maxUsesPerCustomer: number;\n  bogoRequiredQty: number;\n  bogoGetQty:      number;\n  bogoPctOff:      number;\n  flashSaleStartsAt: string;\n  flashSaleEndsAt:   string;\n  startsAt:        string;\n  expiresAt:       string;\n}\n\n// ── Discount type config ─────────────────────────────────────────────────────\nconst TYPES: { type: DiscountType; label: string; icon: any; desc: string; color: string }[] = [\n  { type: \"PERCENTAGE\",    icon: Tag,      label: \"Percentage Off\",  desc: \"% off order or products\",        color: \"#7C3AED\" },\n  { type: \"FIXED\",         icon: Tag,      label: \"Fixed Amount\",    desc: \"$ fixed discount\",                color: \"#3B82F6\" },\n  { type: \"BOGO\",          icon: Gift,     label: \"Buy X Get Y\",     desc: \"Buy X items, get Y free/off\",    color: \"#10B981\" },\n  { type: \"TIERED\",        icon: Layers,   label: \"Volume Tiers\",    desc: \"More items = bigger discount\",   color: \"#F59E0B\" },\n  { type: \"FLASH_SALE\",    icon: Timer,    label: \"Flash Sale\",      desc: \"Time-limited deep discount\",     color: \"#EF4444\" },\n  { type: \"FREE_SHIPPING\", icon: Package,  label: \"Free Shipping\",   desc: \"Free shipping on qualifying orders\", color: \"#06B6D4\" },\n  { type: \"BUNDLE\",        icon: Repeat2,  label: \"Bundle Deal\",     desc: \"Spend X, get Y\",                 color: \"#8B5CF6\" },\n];\n\n// ── Status badge ─────────────────────────────────────────────────────────────\nfunction StatusBadge({ status }: { status: string }) {\n  const cfg = {\n    ACTIVE:    { bg: \"rgba(16,185,129,0.1)\",  color: \"#10B981\", dot: \"#10B981\", label: \"Active\"    },\n    PAUSED:    { bg: \"rgba(245,158,11,0.1)\",  color: \"#F59E0B\", dot: \"#F59E0B\", label: \"Paused\"    },\n    EXPIRED:   { bg: \"rgba(239,68,68,0.1)\",   color: \"#EF4444\", dot: \"#EF4444\", label: \"Expired\"   },\n    SCHEDULED: { bg: \"rgba(59,130,246,0.1)\",  color: \"#3B82F6\", dot: \"#3B82F6\", label: \"Scheduled\" },\n  }[status] || { bg: cardBg, color: \"var(--text-muted,#666)\", dot: \"var(--text-muted,#666)\", label: status };\n\n  return (\n    <span className=\"inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold\"\n      style={{ background: cfg.bg, color: cfg.color }}>\n      <span className=\"w-1.5 h-1.5 rounded-full\" style={{ background: cfg.dot }} />\n      {cfg.label}\n    </span>\n  );\n}\n\n// ── Flash countdown ───────────────────────────────────────────────────────────\nfunction FlashCountdown({ endsAt }: { endsAt: string }) {\n  const [remaining, setRemaining] = useState(\"\");\n\n  useEffect(() => {\n    const calc = () => {\n      const diff = new Date(endsAt).getTime() - Date.now();\n      if (diff <= 0) { setRemaining(\"Ended\"); return; }\n      const h = Math.floor(diff / 3600000);\n      const m = Math.floor((diff % 3600000) / 60000);\n      const s = Math.floor((diff % 60000) / 1000);\n      setRemaining(`${h}h ${m}m ${s}s`);\n    };\n    calc();\n    const t = setInterval(calc, 1000);\n    return () => clearInterval(t);\n  }, [endsAt]);\n\n  return (\n    <span className=\"inline-flex items-center gap-1 text-[11px] font-bold\"\n      style={{ color: \"var(--error)\" }}>\n      <Timer size={10} /> {remaining}\n    </span>\n  );\n}\n\n// ── Discount card ────────────────────────────────────────────────────────────\nfunction DiscountCard({ d, storeId, onDelete }: { d: any; storeId: string; onDelete: (id: string) => void }) {\n  const qc       = useQueryClient();\n  const typeConf = TYPES.find(t => t.type === d.type) || TYPES[0];\n  const Icon     = typeConf.icon;\n\n  const toggleMut = useMutation({\n    mutationFn: () => api.patch(`/discounts/${storeId}/${d.id}/toggle`),\n    onSuccess:  () => qc.invalidateQueries({ queryKey: [\"discounts\"] }),\n  });\n\n  const isActive  = d.status === \"ACTIVE\";\n  const usedPct   = d.maxUses ? Math.min((d.usedCount / d.maxUses) * 100, 100) : 0;\n\n  return (\n    <div className=\"rounded-2xl p-5 transition-all hover:-translate-y-0.5\"\n      style={{ background: cardBg, border: \"1px solid var(--border-color,rgba(107,53,232,0.08))\", boxShadow: \"var(--shadow-sm)\" }}>\n      {/* Header */}\n      <div className=\"flex items-start justify-between mb-3\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0\"\n            style={{ background: typeConf.color + \"18\", border: `1px solid ${typeConf.color}30` }}>\n            <Icon size={15} style={{ color: typeConf.color }} />\n          </div>\n          <div>\n            <div className=\"font-bold text-sm\" style={{ color: txPrimary }}>{d.name}</div>\n            <div className=\"text-[11px] mt-0.5\" style={{ color: tx }}>{typeConf.label}</div>\n          </div>\n        </div>\n        <StatusBadge status={d.status} />\n      </div>\n\n      {/* Value display */}\n      <div className=\"flex items-center gap-2 mb-3 flex-wrap\">\n        <span className=\"text-lg font-black\" style={{ color: typeConf.color }}>\n          {d.type === \"FREE_SHIPPING\" ? \"Free Shipping\"\n            : d.type === \"BOGO\" ? `Buy ${d.bogoRequiredQty} Get ${d.bogoGetQty}`\n            : d.type === \"TIERED\" ? `Up to ${Math.max(...((d.tiers || []) as any[]).map((t: any) => t.discount || 0))}% off`\n            : d.valueType === \"PERCENTAGE\" ? `${d.value}% off`\n            : `$${d.value} off`}\n        </span>\n        {d.minOrderValue > 0 && (\n          <span className=\"text-[11px] px-2 py-0.5 rounded-full\"\n            style={{ background: cardBg, color: \"var(--text-muted,#666)\", border: \"1px solid var(--border-color,rgba(107,53,232,0.08))\" }}>\n            Min ${d.minOrderValue}\n          </span>\n        )}\n        {d.isAutomatic && (\n          <span className=\"text-[11px] px-2 py-0.5 rounded-full\"\n            style={{ background: \"rgba(107,53,232,0.12)\", color: \"#6B35E8\", border: \"1px solid var(--accent-border)\" }}>\n            Automatic\n          </span>\n        )}\n        {d.flashSaleEndsAt && new Date(d.flashSaleEndsAt) > new Date() && (\n          <FlashCountdown endsAt={d.flashSaleEndsAt} />\n        )}\n      </div>\n\n      {/* Tiered preview */}\n      {d.type === \"TIERED\" && d.tiers && (\n        <div className=\"flex gap-1.5 mb-3 flex-wrap\">\n          {(d.tiers as TierRow[]).map((t, i) => (\n            <span key={i} className=\"text-[10px] font-bold px-2 py-0.5 rounded-lg\"\n              style={{ background: cardBg, color: tx, border: `1px solid ${borderCol}` }}>\n              {t.minQty}+ → {t.discount}% off\n            </span>\n          ))}\n        </div>\n      )}\n\n      {/* Usage bar */}\n      {d.maxUses && (\n        <div className=\"mb-3\">\n          <div className=\"flex justify-between text-[11px] mb-1\" style={{ color: tx }}>\n            <span>{d.usedCount} uses</span>\n            <span>{d.maxUses} max</span>\n          </div>\n          <div className=\"h-1.5 rounded-full\" style={{ background: cardBg }}>\n            <div className=\"h-full rounded-full transition-all\"\n              style={{ width: usedPct + \"%\", background: usedPct > 80 ? \"#EF4444\" : typeConf.color }} />\n          </div>\n        </div>\n      )}\n\n      {/* Dates */}\n      {(d.startsAt || d.expiresAt) && (\n        <div className=\"text-[11px] mb-3\" style={{ color: tx }}>\n          {d.startsAt && <span>Starts: {new Date(d.startsAt).toLocaleDateString()} · </span>}\n          {d.expiresAt && <span>Expires: {new Date(d.expiresAt).toLocaleDateString()}</span>}\n        </div>\n      )}\n\n      {/* Actions */}\n      <div className=\"flex items-center justify-between pt-3\" style={{ borderTop: `1px solid ${borderCol}` }}>\n        <div className=\"flex items-center gap-1.5\">\n          <span className=\"text-[11px]\" style={{ color: tx }}>\n            {d._count?.usages || d.usedCount || 0} uses · ${((d._count?.usages || 0) * 0).toFixed(0)} saved\n          </span>\n        </div>\n        <div className=\"flex items-center gap-1\">\n          <button onClick={() => toggleMut.mutate()}\n            className=\"p-2 rounded-lg transition-all text-xs font-bold flex items-center gap-1\"\n            style={{ color: isActive ? \"var(--success)\" : tx, background: isActive ? \"rgba(16,185,129,0.08)\" : cardBg }}>\n            {isActive ? <ToggleRight size={14} /> : <ToggleLeft size={14} />}\n            {isActive ? \"On\" : \"Off\"}\n          </button>\n          <button onClick={() => onDelete(d.id)}\n            className=\"p-2 rounded-lg transition-all\"\n            style={{ color: tx }}\n            onMouseEnter={e => (e.currentTarget as HTMLElement).style.color = \"var(--error)\"}\n            onMouseLeave={e => (e.currentTarget as HTMLElement).style.color = tx}>\n            <Trash2 size={13} />\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// ── Tiered editor ─────────────────────────────────────────────────────────────\nfunction TierEditor({ tiers, onChange }: { tiers: TierRow[]; onChange: (t: TierRow[]) => void }) {\n  const add = () => onChange([...tiers, { minQty: tiers.length > 0 ? tiers[tiers.length-1].minQty + 3 : 2, discount: 10 }]);\n  const del = (i: number) => onChange(tiers.filter((_, idx) => idx !== i));\n  const set = (i: number, k: keyof TierRow, v: number) => {\n    const next = [...tiers]; next[i] = { ...next[i], [k]: v }; onChange(next);\n  };\n\n  return (\n    <div className=\"space-y-2\">\n      {tiers.map((t, i) => (\n        <div key={i} className=\"flex items-center gap-2\">\n          <span className=\"text-xs\" style={{ color: tx, width: 60 }}>Buy {i === 0 ? \"≥\" : \"≥\"}</span>\n          <input type=\"number\" value={t.minQty} min={1}\n            onChange={e => set(i, \"minQty\", Number(e.target.value))}\n            className=\"w-20 rounded-lg px-2 py-1.5 text-xs outline-none\"\n            style={{ background: cardBg, border: `1px solid ${borderCol}`, color: txPrimary }} />\n          <span className=\"text-xs\" style={{ color: tx }}>items →</span>\n          <input type=\"number\" value={t.discount} min={1} max={100}\n            onChange={e => set(i, \"discount\", Number(e.target.value))}\n            className=\"w-20 rounded-lg px-2 py-1.5 text-xs outline-none\"\n            style={{ background: cardBg, border: `1px solid ${borderCol}`, color: txPrimary }} />\n          <span className=\"text-xs\" style={{ color: tx }}>% off</span>\n          <button onClick={() => del(i)} className=\"p-1 rounded\" style={{ color: tx }}>\n            <X size={12} />\n          </button>\n        </div>\n      ))}\n      <button onClick={add}\n        className=\"flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg transition-all\"\n        style={{ color: \"#6B35E8\", background: \"rgba(107,53,232,0.12)\", border: \"1px solid var(--accent-border)\" }}>\n        <Plus size={11} /> Add Tier\n      </button>\n    </div>\n  );\n}\n\n// ── Main page ─────────────────────────────────────────────────────────────────\nexport default function DiscountsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:  false ? cardBg : \"#fff\",\n    border:false ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:  false ? \"#F0ECFF\" : \"#130D2E\",\n    muted: false ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint: false ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n    input: false ? \"rgba(255,255,255,0.05)\" : \"#F5F3FF\",\n  };\n  const qc      = useQueryClient();\n  const user    = useAuthStore(s => s.user);\n  const storeId = user?.stores?.[0]?.id;\n\n  const [modal, setModal]       = useState(false);\n  const [selType, setSelType]   = useState<DiscountType | null>(null);\n  const [tiers, setTiers]       = useState<TierRow[]>([{ minQty: 2, discount: 10 }, { minQty: 5, discount: 20 }]);\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const tx = isDark ? tx : \"rgba(19,13,46,0.55)\";\n  const txPrimary = isDark ? \"#F0ECFF\" : \"#130D2E\";\n  const cardBg = isDark ? \"#181230\" : \"#ffffff\";\n  const borderCol = isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(107,53,232,0.09)\";\n  const [filter, setFilter]     = useState<string>(\"ALL\");\n\n  const { data: discounts = [], isLoading } = useQuery({\n    queryKey: [\"discounts\", storeId],\n    queryFn:  () => api.get(`/discounts/${storeId}`).then(r => r.data.data),\n    enabled:  !!storeId,\n  });\n\n  const createMut = useMutation({\n    mutationFn: (d: any) => api.post(`/discounts/${storeId}`, d),\n    onSuccess:  () => {\n      toast.success(\"Discount created!\");\n      qc.invalidateQueries({ queryKey: [\"discounts\"] });\n      setModal(false); setSelType(null);\n    },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to create discount\"),\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id: string) => api.delete(`/discounts/${storeId}/${id}`),\n    onSuccess:  () => { toast.success(\"Deleted\"); qc.invalidateQueries({ queryKey: [\"discounts\"] }); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Operation failed\"),\n  });\n\n  // Form state\n  const [form, setForm] = useState<Partial<DiscountForm>>({\n    type: \"PERCENTAGE\", valueType: \"PERCENTAGE\", value: 10,\n    isAutomatic: true, stackable: false, priority: 0,\n    bogoRequiredQty: 2, bogoGetQty: 1, bogoPctOff: 100,\n  });\n\n  const set = (k: string, v: any) => setForm(f => ({ ...f, [k]: v }));\n\n  const handleSubmit = () => {\n    if (!form.name || !form.type) return toast.error(\"Name and type required\");\n    const payload = {\n      ...form,\n      tiers: form.type === \"TIERED\" ? tiers : undefined,\n    };\n    createMut.mutate(payload);\n  };\n\n  const filtered = discounts.filter((d: any) =>\n    filter === \"ALL\" ? true : d.status === filter || d.type === filter\n  );\n\n  const typeConf = selType ? TYPES.find(t => t.type === selType) : null;\n\n  // Stats\n  const totalActive = discounts.filter((d: any) => d.status === \"ACTIVE\").length;\n  const flashSales  = discounts.filter((d: any) => d.type === \"FLASH_SALE\" && d.status === \"ACTIVE\").length;\n  const autoDiscount = discounts.filter((d: any) => d.isAutomatic).length;\n\n  const inp = { background: cardBg, border: `1px solid ${borderCol}`, color: txPrimary };\n\n  return (\n    \n      <div className=\"space-y-5\">\n        {/* Header */}\n        <div className=\"flex items-center justify-between\">\n          <div>\n            <h1 className=\"text-xl font-black tracking-tight\" style={{ color: txPrimary }}>Discount Engine</h1>\n            <p className=\"text-xs mt-1\" style={{ color: tx }}>\n              BOGO, flash sales, volume tiers, automatic discounts - all in one place\n            </p>\n          </div>\n          <button onClick={() => { setModal(true); setSelType(null); }}\n            className=\"flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-[#ffffff] transition-all hover:opacity-90\"\n            style={{ background: \"#10B981\", boxShadow: \"0 4px 12px rgba(16,185,129,0.3)\" }}>\n            <Plus size={15} /> New Discount\n          </button>\n        </div>\n\n        {/* Stats */}\n        <div className=\"grid grid-cols-3 gap-4\">\n          {[\n            { label: \"Active Discounts\", value: totalActive,   icon: Tag,      color: \"#7C3AED\" },\n            { label: \"Flash Sales Live\", value: flashSales,    icon: Timer,    color: \"#EF4444\" },\n            { label: \"Auto Discounts\",   value: autoDiscount,  icon: Zap,      color: \"#10B981\" },\n          ].map(({ label, value, icon: Icon, color }) => (\n            <div key={label} className=\"rounded-2xl p-4\"\n              style={{ background: cardBg, border: `1px solid ${borderCol}`, boxShadow: \"var(--shadow-sm)\" }}>\n              <div className=\"flex items-center gap-3\">\n                <div className=\"w-9 h-9 rounded-xl flex items-center justify-center\"\n                  style={{ background: color + \"18\", border: `1px solid ${color}30` }}>\n                  <Icon size={15} style={{ color }} />\n                </div>\n                <div>\n                  <div className=\"text-xl font-black\" style={{ color: txPrimary }}>{value}</div>\n                  <div className=\"text-[11px]\" style={{ color: tx }}>{label}</div>\n                </div>\n              </div>\n            </div>\n          ))}\n        </div>\n\n        {/* Filter tabs */}\n        <div className=\"flex items-center gap-1.5 flex-wrap\">\n          {[\"ALL\", \"ACTIVE\", \"PAUSED\", \"BOGO\", \"TIERED\", \"FLASH_SALE\", \"FREE_SHIPPING\"].map(f => (\n            <button key={f} onClick={() => setFilter(f)}\n              className=\"px-3 py-1.5 rounded-lg text-xs font-semibold transition-all capitalize\"\n              style={{\n                background: filter === f ? \"rgba(107,53,232,0.12)\" : cardBg,\n                color:      filter === f ? \"#6B35E8\"     : tx,\n                border:     `1px solid ${filter === f ? \"rgba(107,53,232,0.4)\" : borderCol}`,\n              }}>\n              {f.toLowerCase().replace(/_/g, \" \")}\n            </button>\n          ))}\n        </div>\n\n        {/* Discount grid */}\n        {isLoading ? (\n          <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n            {[1,2,3].map(i => (\n              <div key={i} className=\"rounded-2xl h-40 skeleton\" />\n            ))}\n          </div>\n        ) : filtered.length === 0 ? (\n          <div className=\"rounded-2xl p-16 text-center\"\n            style={{ background: cardBg, border: \"1px dashed rgba(255,255,255,0.06)\" }}>\n            <Tag size={36} className=\"mx-auto mb-4\" style={{ color: tx }} />\n            <h3 className=\"font-bold mb-2\" style={{ color: txPrimary }}>No discounts yet</h3>\n            <p className=\"text-sm mb-5\" style={{ color: tx }}>\n              Create your first discount to drive more sales.\n            </p>\n            <button onClick={() => setModal(true)}\n              className=\"px-5 py-2.5 rounded-xl text-sm font-bold text-[#ffffff]\"\n              style={{ background: \"#10B981\" }}>\n              + Create Discount\n            </button>\n          </div>\n        ) : (\n          <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n            {filtered.map((d: any) => (\n              <DiscountCard key={d.id} d={d} storeId={storeId!} onDelete={id => deleteMut.mutate(id)} />\n            ))}\n          </div>\n        )}\n\n        {/* ── Create modal ──────────────────────────────────────────────── */}\n        {modal && (\n          <div className=\"fixed inset-0 z-50 flex items-center justify-center p-4\"\n            style={{ background: \"var(--bg-overlay)\", backdropFilter: \"blur(8px)\" }}>\n            <div className=\"w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl\"\n              style={{ background: cardBg, border: `1px solid ${borderCol}`, boxShadow: \"var(--shadow-xl)\" }}>\n\n              {/* Modal header */}\n              <div className=\"flex items-center justify-between p-6 border-b\" style={{ borderColor: borderCol }}>\n                <h2 className=\"text-lg font-black\" style={{ color: txPrimary }}>\n                  {selType ? `Create ${typeConf?.label}` : \"Choose Discount Type\"}\n                </h2>\n                <button onClick={() => { setModal(false); setSelType(null); }}\n                  className=\"p-2 rounded-lg\" style={{ color: tx }}>\n                  <X size={16} />\n                </button>\n              </div>\n\n              <div className=\"p-6\">\n                {/* Type picker */}\n                {!selType ? (\n                  <div className=\"grid grid-cols-2 sm:grid-cols-3 gap-3\">\n                    {TYPES.map(t => (\n                      <button key={t.type} onClick={() => { setSelType(t.type); set(\"type\", t.type); }}\n                        className=\"flex flex-col items-start gap-2 p-4 rounded-xl text-left transition-all hover:-translate-y-0.5\"\n                        style={{ background: cardBg, border: `1px solid ${borderCol}` }}\n                        onMouseEnter={e => (e.currentTarget as HTMLElement).style.borderColor = t.color + \"60\"}\n                        onMouseLeave={e => (e.currentTarget as HTMLElement).style.borderColor = borderCol}>\n                        <div className=\"w-9 h-9 rounded-xl flex items-center justify-center\"\n                          style={{ background: t.color + \"18\", border: `1px solid ${t.color}30` }}>\n                          <t.icon size={16} style={{ color: t.color }} />\n                        </div>\n                        <div>\n                          <div className=\"text-sm font-bold\" style={{ color: txPrimary }}>{t.label}</div>\n                          <div className=\"text-[11px] mt-0.5\" style={{ color: tx }}>{t.desc}</div>\n                        </div>\n                      </button>\n                    ))}\n                  </div>\n                ) : (\n                  <div className=\"space-y-5\">\n                    {/* Back */}\n                    <button onClick={() => setSelType(null)}\n                      className=\"flex items-center gap-1.5 text-sm font-semibold\"\n                      style={{ color: \"#6B35E8\" }}>\n                      ← Choose different type\n                    </button>\n\n                    {/* Basic info */}\n                    <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                      <div>\n                        <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Discount Name *</label>\n                        <input value={form.name || \"\"} onChange={e => set(\"name\", e.target.value)}\n                          placeholder=\"e.g. Summer Sale 20% Off\"\n                          className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none transition-all\"\n                          style={inp} />\n                      </div>\n                      <div>\n                        <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Priority (higher = first)</label>\n                        <input type=\"number\" value={form.priority || 0} onChange={e => set(\"priority\", Number(e.target.value))}\n                          className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none transition-all\"\n                          style={inp} />\n                      </div>\n                    </div>\n\n                    {/* Type-specific fields */}\n                    {(selType === \"PERCENTAGE\" || selType === \"BUNDLE\") && (\n                      <div className=\"grid grid-cols-2 gap-4\">\n                        <div>\n                          <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Discount %</label>\n                          <input type=\"number\" min={1} max={100} value={form.value || 10}\n                            onChange={e => set(\"value\", Number(e.target.value))}\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none transition-all\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Max $ off (optional)</label>\n                          <input type=\"number\" min={0} value={form.maxDiscount || \"\"} placeholder=\"No cap\"\n                            onChange={e => set(\"maxDiscount\", Number(e.target.value))}\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none transition-all\" style={inp} />\n                        </div>\n                      </div>\n                    )}\n\n                    {selType === \"FIXED\" && (\n                      <div>\n                        <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Fixed Amount Off ($)</label>\n                        <input type=\"number\" min={1} value={form.value || 10}\n                          onChange={e => set(\"value\", Number(e.target.value))}\n                          className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none transition-all\" style={inp} />\n                      </div>\n                    )}\n\n                    {selType === \"BOGO\" && (\n                      <div className=\"rounded-xl p-4 space-y-3\" style={{ background: cardBg, border: `1px solid ${borderCol}` }}>\n                        <div className=\"text-xs font-bold\" style={{ color: tx }}>BOGO Configuration</div>\n                        <div className=\"grid grid-cols-3 gap-3\">\n                          <div>\n                            <label className=\"block text-xs mb-1\" style={{ color: tx }}>Buy (qty)</label>\n                            <input type=\"number\" min={1} value={form.bogoRequiredQty || 2}\n                              onChange={e => set(\"bogoRequiredQty\", Number(e.target.value))}\n                              className=\"w-full rounded-lg px-2 py-2 text-sm outline-none\" style={inp} />\n                          </div>\n                          <div>\n                            <label className=\"block text-xs mb-1\" style={{ color: tx }}>Get (qty)</label>\n                            <input type=\"number\" min={1} value={form.bogoGetQty || 1}\n                              onChange={e => set(\"bogoGetQty\", Number(e.target.value))}\n                              className=\"w-full rounded-lg px-2 py-2 text-sm outline-none\" style={inp} />\n                          </div>\n                          <div>\n                            <label className=\"block text-xs mb-1\" style={{ color: tx }}>% off free item</label>\n                            <input type=\"number\" min={1} max={100} value={form.bogoPctOff || 100}\n                              onChange={e => set(\"bogoPctOff\", Number(e.target.value))}\n                              className=\"w-full rounded-lg px-2 py-2 text-sm outline-none\" style={inp} />\n                          </div>\n                        </div>\n                        <p className=\"text-[11px]\" style={{ color: tx }}>\n                          Customer buys {form.bogoRequiredQty || 2}, gets {form.bogoGetQty || 1} at {form.bogoPctOff || 100}% off\n                        </p>\n                      </div>\n                    )}\n\n                    {selType === \"TIERED\" && (\n                      <div className=\"rounded-xl p-4\" style={{ background: cardBg, border: `1px solid ${borderCol}` }}>\n                        <div className=\"text-xs font-bold mb-3\" style={{ color: tx }}>Volume Tiers</div>\n                        <TierEditor tiers={tiers} onChange={setTiers} />\n                      </div>\n                    )}\n\n                    {selType === \"FLASH_SALE\" && (\n                      <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                        <div>\n                          <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Discount %</label>\n                          <input type=\"number\" min={1} max={100} value={form.value || 30}\n                            onChange={e => set(\"value\", Number(e.target.value))}\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Starts</label>\n                          <input type=\"datetime-local\" value={form.flashSaleStartsAt || \"\"}\n                            onChange={e => set(\"flashSaleStartsAt\", e.target.value)}\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: tx }}>Ends *</label>\n                          <input type=\"datetime-local\" value={form.flashSaleEndsAt || \"\"}\n                            onChange={e => set(\"flashSaleEndsAt\", e.target.value)}\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none\" style={inp} />\n                        </div>\n                      </div>\n                    )}\n\n                    {/* Conditions */}\n                    <div className=\"pt-3 border-t\" style={{ borderColor: borderCol }}>\n                      <div className=\"text-xs font-bold mb-3\" style={{ color: tx }}>Conditions</div>\n                      <div className=\"grid grid-cols-2 gap-3\">\n                        <div>\n                          <label className=\"block text-xs mb-1\" style={{ color: tx }}>Min order value ($)</label>\n                          <input type=\"number\" min={0} value={form.minOrderValue || \"\"} placeholder=\"None\"\n                            onChange={e => set(\"minOrderValue\", Number(e.target.value))}\n                            className=\"w-full rounded-lg px-3 py-2 text-sm outline-none\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs mb-1\" style={{ color: tx }}>Max total uses</label>\n                          <input type=\"number\" min={0} value={form.maxUses || \"\"} placeholder=\"Unlimited\"\n                            onChange={e => set(\"maxUses\", Number(e.target.value))}\n                            className=\"w-full rounded-lg px-3 py-2 text-sm outline-none\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs mb-1\" style={{ color: tx }}>Valid from</label>\n                          <input type=\"date\" value={form.startsAt || \"\"}\n                            onChange={e => set(\"startsAt\", e.target.value)}\n                            className=\"w-full rounded-lg px-3 py-2 text-sm outline-none\" style={inp} />\n                        </div>\n                        <div>\n                          <label className=\"block text-xs mb-1\" style={{ color: tx }}>Expires</label>\n                          <input type=\"date\" value={form.expiresAt || \"\"}\n                            onChange={e => set(\"expiresAt\", e.target.value)}\n                            className=\"w-full rounded-lg px-3 py-2 text-sm outline-none\" style={inp} />\n                        </div>\n                      </div>\n                    </div>\n\n                    {/* Options */}\n                    <div className=\"flex flex-wrap gap-3 pt-3 border-t\" style={{ borderColor: borderCol }}>\n                      {[\n                        { key: \"isAutomatic\",   label: \"Automatic (no code)\" },\n                        { key: \"stackable\",      label: \"Stackable\" },\n                        { key: \"freeShipping\",   label: \"Includes free shipping\" },\n                        { key: \"firstOrderOnly\", label: \"First order only\" },\n                      ].map(({ key, label }) => (\n                        <button key={key} onClick={() => set(key, !form[key as keyof DiscountForm])}\n                          className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all\"\n                          style={{\n                            background: form[key as keyof DiscountForm] ? \"rgba(107,53,232,0.12)\" : cardBg,\n                            color:      form[key as keyof DiscountForm] ? \"#6B35E8\"     : tx,\n                            border:     `1px solid ${form[key as keyof DiscountForm] ? \"var(--accent-border)\" : borderCol}`,\n                          }}>\n                          <div className=\"w-3.5 h-3.5 rounded flex items-center justify-center\"\n                            style={{ background: form[key as keyof DiscountForm] ? \"#6B35E8\" : cardBg, border: `1px solid ${form[key as keyof DiscountForm] ? \"#6B35E8\" : borderCol}` }}>\n                            {form[key as keyof DiscountForm] && <span className=\"text-[#ffffff] text-[8px]\">✓</span>}\n                          </div>\n                          {label}\n                        </button>\n                      ))}\n                    </div>\n\n                    {/* Submit */}\n                    <div className=\"flex gap-3 pt-2\">\n                      <button onClick={handleSubmit} disabled={createMut.isPending}\n                        className=\"flex-1 py-3 rounded-xl text-sm font-bold text-[#ffffff] hover:opacity-90 disabled:opacity-60 transition-all\"\n                        style={{ background: \"#10B981\", boxShadow: \"0 4px 12px rgba(16,185,129,0.25)\" }}>\n                        {createMut.isPending ? \"Creating…\" : \"Create Discount\"}\n                      </button>\n                      <button onClick={() => { setModal(false); setSelType(null); }}\n                        className=\"px-5 py-3 rounded-xl text-sm font-semibold transition-all\"\n                        style={{ background: cardBg, color: tx, border: `1px solid ${borderCol}` }}>\n                        Cancel\n                      </button>\n                    </div>\n                  </div>\n                )}\n              </div>\n            </div>\n          </div>\n        )}\n      </div>\n    \n  );\n}\n","frontend/src/app/dashboard/autopilot/page.tsx":"\"use client\";\n// ============================================================\n// Autopilot Dashboard\n// Path: frontend/src/app/dashboard/autopilot/page.tsx\n//\n// Shows seller what's running on autopilot.\n// Connect CJ once. Everything else handled.\n// ============================================================\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence }               from \"framer-motion\";\nimport { api }         from \"../../../lib/api\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport {\n  Zap, Check, AlertCircle, ChevronRight,\n  Eye, EyeOff, Loader2, ExternalLink,\n  Package, Truck, RefreshCw, Star, DollarSign,\n  Bell, Shield, Clock,\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst AUTOPILOT_TASKS = [\n  { icon: Package,   label: \"New orders auto-sent to supplier\",  interval: \"Every 15 min\",  color: \"#34d399\", key: \"fulfillment\" },\n  { icon: Truck,     label: \"Tracking synced + customer notified\",interval: \"Every 2 hours\", color: \"#60a5fa\", key: \"tracking\" },\n  { icon: Bell,      label: \"Store health monitoring\",           interval: \"Every 2 hours\", color: \"#a78bfa\", key: \"pulse\" },\n  { icon: DollarSign,label: \"Supplier stock + price sync\",       interval: \"Every 6 hours\", color: \"#fbbf24\", key: \"stock\" },\n  { icon: Shield,    label: \"Profit protection rules\",           interval: \"Every 6 hours\", color: \"#f97316\", key: \"rules\" },\n  { icon: Star,      label: \"Review requests to customers\",      interval: \"Every hour\",    color: \"#ec4899\", key: \"reviews\" },\n  { icon: RefreshCw, label: \"Market intelligence refresh\",       interval: \"Daily\",         color: \"#8b5cf6\", key: \"market\" },\n];\n\nexport default function AutopilotPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = isDark ? { card:\"#181230\", border:\"rgba(255,255,255,0.06)\", text:\"#fff\", muted:\"rgba(255,255,255,0.38)\", faint:\"rgba(255,255,255,0.04)\" } : { card:\"#fff\", border:\"rgba(15,5,32,0.07)\", text:\"#0D0918\", muted:\"rgba(13,9,24,0.45)\", faint:\"rgba(15,5,32,0.03)\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const qc      = useQueryClient();\n\n  const [showCJForm, setShowCJForm]   = useState(false);\n  const [cjEmail, setCJEmail]         = useState(\"\");\n  const [cjPass, setCJPass]           = useState(\"\");\n  const [showPass, setShowPass]       = useState(false);\n\n  const { data: status, isLoading } = useQuery({\n    queryKey: [\"autopilot-status\", storeId],\n    queryFn:  async () => {\n      const r = await api.get(`/fulfillment/status/${storeId}`);\n      return r.data.data;\n    },\n    enabled:  !!storeId,\n    refetchInterval: 30000,\n  });\n\n  const connectCJ = useMutation({\n    mutationFn: async () => api.post(\"/fulfillment/connect/cj\", { storeId, email: cjEmail, password: cjPass }),\n    onSuccess: (r) => {\n      if (r.data.success) {\n        toast.success(\"CJDropshipping connected! Autopilot is now active.\");\n        qc.invalidateQueries({queryKey:[\"autopilot-status\", storeId]});\n        setShowCJForm(false);\n        setCJEmail(\"\");\n        setCJPass(\"\");\n      } else {\n        toast.error(r.data.message);\n      }\n    },\n    onError: () => toast.error(\"Connection failed - check credentials\"),\n  });\n\n  const disconnectCJ = useMutation({\n    mutationFn: async () => api.post(\"/fulfillment/disconnect\", { storeId, provider: \"cjdropshipping\" }),\n    onSuccess: () => {\n      toast.success(\"CJ disconnected\");\n      qc.invalidateQueries({queryKey:[\"autopilot-status\", storeId]});\n    },\n  });\n\n  const runNow = useMutation({\n    mutationFn: async () => api.post(\"/fulfillment/fulfill-now\", { storeId }),\n    onSuccess: (r) => {\n      const { fulfilled, failed, skipped } = r.data.data;\n      if (fulfilled > 0) toast.success(`${fulfilled} orders fulfilled!`);\n      else if (skipped > 0) toast(\"No new orders to fulfill\", { icon: \"ℹ️\" });\n      else toast(\"Nothing to fulfill right now\", { icon: \"✅\" });\n    },\n  });\n\n  const cjConnected = status?.cj?.connected;\n  const isActive    = cjConnected;\n\n  return (\n    \n      <div className=\"min-h-screen p-6\" style={{ background: \"#07070e\" }}>\n        <div className=\"max-w-3xl mx-auto\">\n\n          {/* Header */}\n          <div className=\"mb-6\">\n            <div className=\"flex items-center gap-3 mb-1\">\n              <h1 className=\"text-xl font-semibold text-white\">Store Autopilot</h1>\n              {isActive && (\n                <motion.div className=\"flex items-center gap-1.5 px-3 py-1 rounded-full\"\n                  style={{ background: \"rgba(52,211,153,0.15)\", border: \"1px solid rgba(52,211,153,0.3)\" }}\n                  animate={{ opacity: [1, 0.7, 1] }} transition={{ duration: 2, repeat: Infinity }}>\n                  <div className=\"w-1.5 h-1.5 rounded-full\" style={{ background: \"#34d399\" }} />\n                  <span className=\"text-xs font-medium\" style={{ color: \"#34d399\" }}>Running</span>\n                </motion.div>\n              )}\n            </div>\n            <p className=\"text-sm\" style={{ color: t.muted }}>\n              Connect your supplier once - KAI handles everything automatically\n            </p>\n          </div>\n\n          {/* What autopilot does */}\n          <div className=\"rounded-2xl p-5 mb-6\" style={{ background: \"rgba(255,255,255,0.03)\", border: \"1px solid rgba(255,255,255,0.07)\" }}>\n            <p className=\"text-xs font-semibold uppercase tracking-wider mb-4\" style={{ color: t.muted, fontSize: \"10px\" }}>\n              What runs automatically\n            </p>\n            <div className=\"space-y-3\">\n              {AUTOPILOT_TASKS.map((task, i) => (\n                <motion.div key={task.key}\n                  className=\"flex items-center gap-3\"\n                  initial={{ opacity: 0, x: -8 }}\n                  animate={{ opacity: 1, x: 0 }}\n                  transition={{ delay: i * 0.06 }}>\n                  <div className=\"w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0\"\n                    style={{ background: isActive ? `${task.color}15` : \"rgba(255,255,255,0.05)\" }}>\n                    <task.icon size={14} style={{ color: isActive ? task.color : t.muted }} />\n                  </div>\n                  <p className=\"flex-1 text-sm\" style={{ color: isActive ? t.text : t.muted }}>\n                    {task.label}\n                  </p>\n                  <span className=\"text-xs\" style={{ color: isActive ? t.muted : t.faint }}>\n                    {task.interval}\n                  </span>\n                  {isActive && (\n                    <div className=\"w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0\"\n                      style={{ background: \"rgba(52,211,153,0.15)\" }}>\n                      <Check size={9} style={{ color: \"#34d399\" }} />\n                    </div>\n                  )}\n                </motion.div>\n              ))}\n            </div>\n          </div>\n\n          {/* CJ Connection */}\n          <div className=\"rounded-2xl overflow-hidden mb-4\" style={{ border: `1px solid ${cjConnected ? \"rgba(52,211,153,0.2)\" : \"rgba(255,255,255,0.08)\"}` }}>\n            <div className=\"px-5 py-4 flex items-center justify-between\"\n              style={{ background: cjConnected ? \"rgba(52,211,153,0.05)\" : \"rgba(255,255,255,0.03)\", borderBottom: \"1px solid rgba(255,255,255,0.06)\" }}>\n              <div className=\"flex items-center gap-3\">\n                <div className=\"w-10 h-10 rounded-xl flex items-center justify-center text-sm font-black\"\n                  style={{ background: cjConnected ? \"rgba(52,211,153,0.15)\" : \"rgba(255,255,255,0.06)\", color: cjConnected ? \"#34d399\" : t.muted }}>\n                  CJ\n                </div>\n                <div>\n                  <p className=\"text-sm font-semibold text-white\">CJDropshipping</p>\n                  <p className=\"text-xs\" style={{ color: t.muted }}>\n                    Free · 400,000+ products · Ships worldwide · No monthly fee\n                  </p>\n                </div>\n              </div>\n              <div className=\"flex items-center gap-2\">\n                {cjConnected\n                  ? <span className=\"text-xs px-2.5 py-1 rounded-full flex items-center gap-1.5\"\n                      style={{ background: \"rgba(52,211,153,0.12)\", color: \"#34d399\" }}>\n                      <Check size={10} />Connected\n                    </span>\n                  : <span className=\"text-xs px-2.5 py-1 rounded-full\"\n                      style={{ background: \"rgba(255,255,255,0.06)\", color: t.muted }}>\n                      Not connected\n                    </span>\n                }\n              </div>\n            </div>\n\n            <div className=\"px-5 py-4\">\n              {cjConnected ? (\n                <div>\n                  <p className=\"text-sm mb-3\" style={{ color: t.text }}>\n                    ✅ Autopilot is active. New orders are automatically sent to CJDropshipping and customers receive tracking updates automatically.\n                  </p>\n                  <p className=\"text-xs mb-4\" style={{ color: t.muted }}>\n                    Connected as: {status?.cj?.email}\n                  </p>\n                  <div className=\"flex gap-2\">\n                    <button onClick={() => runNow.mutate()} disabled={runNow.isPending}\n                      className=\"flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-medium\"\n                      style={{ background: \"rgba(52,211,153,0.1)\", border: \"1px solid rgba(52,211,153,0.2)\", color: \"#34d399\" }}>\n                      {runNow.isPending ? <Loader2 size={11} className=\"animate-spin\" /> : <Zap size={11} />}\n                      {runNow.isPending ? \"Running...\" : \"Fulfill Now\"}\n                    </button>\n                    <button onClick={() => disconnectCJ.mutate()}\n                      className=\"px-4 py-2 rounded-xl text-xs\"\n                      style={{ color: t.muted }}>\n                      Disconnect\n                    </button>\n                  </div>\n                </div>\n              ) : (\n                <div>\n                  {!showCJForm ? (\n                    <div>\n                      <p className=\"text-sm mb-4\" style={{ color: t.muted }}>\n                        Connect your free CJDropshipping account to activate full autopilot. Orders will be fulfilled automatically - you just focus on getting customers.\n                      </p>\n                      <div className=\"flex gap-3\">\n                        <button onClick={() => setShowCJForm(true)}\n                          className=\"flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold\"\n                          style={{ background: \"linear-gradient(135deg,#7c3aed,#5b21b6)\", color: \"#fff\" }}>\n                          <Zap size={14} />Connect CJDropshipping\n                        </button>\n                        <a href=\"https://cjdropshipping.com/register.html\" target=\"_blank\"\n                          className=\"flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-sm\"\n                          style={{ background: \"rgba(255,255,255,0.05)\", border: \"1px solid rgba(255,255,255,0.08)\", color: t.muted }}>\n                          <ExternalLink size={12} />Create free account\n                        </a>\n                      </div>\n                    </div>\n                  ) : (\n                    <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}>\n                      <p className=\"text-sm font-medium text-white mb-4\">Enter your CJDropshipping credentials</p>\n                      <div className=\"space-y-3 mb-4\">\n                        <div>\n                          <label className=\"text-xs mb-1.5 block\" style={{ color: t.muted }}>CJ Email</label>\n                          <input value={cjEmail} onChange={e => setCJEmail(e.target.value)}\n                            placeholder=\"your@email.com\"\n                            type=\"email\"\n                            className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none\"\n                            style={{ background: \"rgba(255,255,255,0.06)\", border: \"1px solid rgba(255,255,255,0.1)\", color: \"rgba(255,255,255,0.85)\" }} />\n                        </div>\n                        <div>\n                          <label className=\"text-xs mb-1.5 block\" style={{ color: t.muted }}>CJ Password</label>\n                          <div className=\"relative\">\n                            <input value={cjPass} onChange={e => setCJPass(e.target.value)}\n                              placeholder=\"••••••••\"\n                              type={showPass ? \"text\" : \"password\"}\n                              className=\"w-full rounded-xl px-3 py-2.5 text-sm outline-none pr-10\"\n                              style={{ background: \"rgba(255,255,255,0.06)\", border: \"1px solid rgba(255,255,255,0.1)\", color: \"rgba(255,255,255,0.85)\" }} />\n                            <button onClick={() => setShowPass(!showPass)}\n                              className=\"absolute right-3 top-1/2 -translate-y-1/2\"\n                              style={{ color: t.muted }}>\n                              {showPass ? <EyeOff size={14} /> : <Eye size={14} />}\n                            </button>\n                          </div>\n                        </div>\n                      </div>\n\n                      <div className=\"flex items-start gap-2 mb-4 px-3 py-2 rounded-xl\"\n                        style={{ background: \"rgba(96,165,250,0.08)\", border: \"1px solid rgba(96,165,250,0.15)\" }}>\n                        <AlertCircle size={12} className=\"mt-0.5 flex-shrink-0\" style={{ color: \"#60a5fa\" }} />\n                        <p className=\"text-xs\" style={{ color: t.muted }}>\n                          Your credentials are stored encrypted and only used to place orders on your behalf. DropOS never stores payment info.\n                        </p>\n                      </div>\n\n                      <div className=\"flex gap-2\">\n                        <button disabled={!cjEmail || !cjPass || connectCJ.isPending}\n                          onClick={() => connectCJ.mutate()}\n                          className=\"flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold\"\n                          style={{ background: (cjEmail && cjPass) ? \"#7c3aed\" : \"rgba(255,255,255,0.05)\", color: (cjEmail && cjPass) ? \"#fff\" : t.muted }}>\n                          {connectCJ.isPending ? <Loader2 size={14} className=\"animate-spin\" /> : <Check size={14} />}\n                          {connectCJ.isPending ? \"Connecting...\" : \"Connect & Activate\"}\n                        </button>\n                        <button onClick={() => { setShowCJForm(false); setCJEmail(\"\"); setCJPass(\"\"); }}\n                          className=\"px-4 py-2.5 rounded-xl text-sm\"\n                          style={{ color: t.muted }}>\n                          Cancel\n                        </button>\n                      </div>\n                    </motion.div>\n                  )}\n                </div>\n              )}\n            </div>\n          </div>\n\n          {/* What seller focuses on instead */}\n          {cjConnected && (\n            <motion.div className=\"rounded-2xl p-5\"\n              style={{ background: \"rgba(124,58,237,0.08)\", border: \"1px solid rgba(124,58,237,0.2)\" }}\n              initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}>\n              <p className=\"text-sm font-semibold text-white mb-3\">\n                🎯 Your only job now\n              </p>\n              <div className=\"space-y-2\">\n                {[\n                  \"Get customers - TikTok, Instagram, WhatsApp\",\n                  \"Add winning products - KAI finds them daily\",\n                  \"Set your prices and let profit rules protect them\",\n                ].map((task, i) => (\n                  <div key={i} className=\"flex items-center gap-2 text-sm\" style={{ color: t.text }}>\n                    <ChevronRight size={12} style={{ color: \"#a78bfa\" }} />\n                    {task}\n                  </div>\n                ))}\n              </div>\n              <p className=\"text-xs mt-3\" style={{ color: t.muted }}>\n                Everything else - fulfillment, tracking, stock sync, reviews - KAI handles it.\n              </p>\n            </motion.div>\n          )}\n        </div>\n      </div>\n    \n  );\n}\n","frontend/src/components/ui/CreditWallet.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../layout/DashboardLayout\";\nimport { Zap, Plus, TrendingUp, AlertTriangle, X, Check } from \"lucide-react\";\nimport { useCreditsStore, CREDIT_COSTS } from \"../../store/credits.store\";\nimport { api } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\n\nconst TOP_UP_PACKS = [\n  { id: \"starter\",    amount: 500,   price: 1500,   label: \"Starter\",    popular: false },\n  { id: \"growth\",     amount: 2000,  price: 5000,   label: \"Growth\",     popular: true  },\n  { id: \"pro\",        amount: 5000,  price: 10000,  label: \"Pro\",        popular: false },\n  { id: \"unlimited\",  amount: 15000, price: 25000,  label: \"Unlimited\",  popular: false },\n];\n\nexport function CreditBadge({ compact = false }: { compact?: boolean }) {\n  const { balance, monthlyLimit } = useCreditsStore();\n  const pct = Math.round((balance / monthlyLimit) * 100);\n  const isLow = pct <= 20;\n  const isCritical = pct <= 5;\n\n  const color = isCritical ? \"#EF4444\" : isLow ? \"#F59E0B\" : \"#10B981\";\n  const bg    = isCritical ? \"rgba(239,68,68,0.1)\" : isLow ? \"rgba(245,158,11,0.1)\" : \"rgba(107,53,232,0.1)\";\n\n  if (compact) {\n    return (\n      <div style={{ display: \"flex\", alignItems: \"center\", gap: 5, padding: \"4px 10px\", borderRadius: 20, background: bg, border: `1px solid ${color}30` }}>\n        <Zap size={11} color={color} />\n        <span style={{ fontSize: 11, fontWeight: 700, color }}>{balance.toLocaleString()}</span>\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n      <Zap size={13} color={color} />\n      <div style={{ flex: 1 }}>\n        <div style={{ display: \"flex\", justifyContent: \"space-between\", marginBottom: 3 }}>\n          <span style={{ fontSize: 11, fontWeight: 600, color: \"currentColor\", opacity: 0.6 }}>KIRO Credits</span>\n          <span style={{ fontSize: 11, fontWeight: 700, color }}>{balance.toLocaleString()} / {monthlyLimit.toLocaleString()}</span>\n        </div>\n        <div style={{ height: 4, borderRadius: 99, background: \"rgba(128,90,213,0.12)\", overflow: \"hidden\" }}>\n          <motion.div\n            initial={{ width: 0 }}\n            animate={{ width: `${pct}%` }}\n            transition={{ duration: 0.8, ease: \"easeOut\" }}\n            style={{ height: \"100%\", borderRadius: 99, background: color }}\n          />\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport function CreditCost({ feature, children }: { feature: keyof typeof CREDIT_COSTS; children?: React.ReactNode }) {\n  const { balance } = useCreditsStore();\n  const cost = CREDIT_COSTS[feature];\n  const canAfford = balance >= cost;\n\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n      {children}\n      <span style={{ fontSize: 11, fontWeight: 600, color: canAfford ? \"#A78BFA\" : \"#EF4444\", display: \"flex\", alignItems: \"center\", gap: 3 }}>\n        <Zap size={10} />\n        {cost} credits\n        {!canAfford && <AlertTriangle size={10} color=\"#EF4444\" />}\n      </span>\n    </div>\n  );\n}\n\nexport function TopUpModal({ onClose }: { onClose: () => void }) {\n  const [loading, setLoading] = useState<string | null>(null);\n  const { setBalance, balance } = useCreditsStore();\n\n  const handleTopUp = async (pack: typeof TOP_UP_PACKS[0]) => {\n    setLoading(pack.id);\n    try {\n      const res = await api.post(\"/billing/credits/topup\", { packId: pack.id });\n      const url = res.data?.data?.authorizationUrl;\n      if (url) {\n        window.location.href = url;\n      } else {\n        // Demo mode - just add credits\n        setBalance(balance + pack.amount);\n        toast.success(`Added ${pack.amount.toLocaleString()} credits!`);\n        onClose();\n      }\n    } catch {\n      toast.error(\"Top-up failed - backend offline\");\n    } finally {\n      setLoading(null);\n    }\n  };\n\n  return (\n    <div style={{ position: \"fixed\", inset: 0, zIndex: 9999, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", padding: 16, background: \"rgba(0,0,0,0.7)\", backdropFilter: \"blur(8px)\" }}\n      onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{ opacity: 0, scale: 0.95, y: 16 }} animate={{ opacity: 1, scale: 1, y: 0 }}\n        style={{ width: \"100%\", maxWidth: 420, borderRadius: 24, background: \"#181230\", border: \"1px solid rgba(255,255,255,0.08)\", overflow: \"hidden\" }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"20px 24px\", borderBottom: \"1px solid rgba(255,255,255,0.06)\" }}>\n          <div>\n            <h2 style={{ fontSize: 16, fontWeight: 800, color: wText, marginBottom: 2 }}>Top Up Credits</h2>\n            <p style={{ fontSize: 12, color: wMuted }}>Credits never expire. Use for KIRO, images, videos.</p>\n          </div>\n          <button onClick={onClose} style={{ color: wMuted, background: \"none\", border: \"none\", cursor: \"pointer\" }}><X size={18} /></button>\n        </div>\n\n        <div style={{ padding: 24, display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 12 }}>\n          {TOP_UP_PACKS.map(pack => (\n            <button key={pack.id} onClick={() => handleTopUp(pack)} disabled={!!loading}\n              style={{ padding: \"16px\", borderRadius: 16, border: `1px solid ${pack.popular ? \"rgba(107,53,232,0.5)\" : \"rgba(255,255,255,0.08)\"}`, background: pack.popular ? \"rgba(107,53,232,0.1)\" : \"rgba(255,255,255,0.03)\", cursor: \"pointer\", textAlign: \"left\", position: \"relative\", opacity: loading ? 0.6 : 1 }}>\n              {pack.popular && <span style={{ position: \"absolute\", top: -8, right: 8, fontSize: 9, fontWeight: 700, padding: \"2px 8px\", borderRadius: 99, background: \"#6B35E8\", color: wText, letterSpacing: \"0.05em\", textTransform: \"uppercase\" }}>Popular</span>}\n              {loading === pack.id\n                ? <div style={{ height: 40, display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <motion.div animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: \"linear\" }}><Zap size={16} color=\"#8B5CF6\" /></motion.div>\n                  </div>\n                : <>\n                    <p style={{ fontSize: 20, fontWeight: 900, color: wText, marginBottom: 2 }}>{pack.amount.toLocaleString()}</p>\n                    <p style={{ fontSize: 11, color: wMuted, marginBottom: 10 }}>credits</p>\n                    <p style={{ fontSize: 15, fontWeight: 800, color: \"#A78BFA\" }}>₦{pack.price.toLocaleString()}</p>\n                  </>\n              }\n            </button>\n          ))}\n        </div>\n\n        <div style={{ padding: \"0 24px 24px\" }}>\n          <div style={{ padding: \"12px 16px\", borderRadius: 12, background: \"rgba(107,53,232,0.06)\", border: \"1px solid rgba(107,53,232,0.15)\", fontSize: 12, color: \"rgba(255,255,255,0.45)\", lineHeight: 1.6 }}>\n            Top-up credits roll over forever. Monthly plan credits reset each billing date. KIRO uses 1 credit per message.\n          </div>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\nexport default function CreditWallet() {\n  const { balance, plan, monthlyLimit, usedThisMonth } = useCreditsStore();\n  const [showTopUp, setShowTopUp] = useState(false);\n  const pct = Math.round((balance / monthlyLimit) * 100);\n  const isLow = pct <= 20;\n\n  return (\n    <>\n      <div style={{ padding: \"14px 16px\", borderRadius: 16, background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 10 }}>\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n            <Zap size={14} color=\"#8B5CF6\" />\n            <span style={{ fontSize: 13, fontWeight: 700, color: wText }}>KIRO Credits</span>\n          </div>\n          <button onClick={() => setShowTopUp(true)}\n            style={{ display: \"flex\", alignItems: \"center\", gap: 4, padding: \"4px 10px\", borderRadius: 8, border: \"1px solid rgba(107,53,232,0.4)\", background: \"rgba(107,53,232,0.12)\", color: \"#A78BFA\", fontSize: 11, fontWeight: 600, cursor: \"pointer\" }}>\n            <Plus size={10} /> Top Up\n          </button>\n        </div>\n\n        <div style={{ display: \"flex\", alignItems: \"baseline\", gap: 4, marginBottom: 8 }}>\n          <span style={{ fontSize: 24, fontWeight: 900, color: isLow ? \"#F59E0B\" : (isDark ? \"#F0ECFF\" : \"#130D2E\") }}>{balance.toLocaleString()}</span>\n          <span style={{ fontSize: 12, color: wMuted }}>/ {monthlyLimit.toLocaleString()} this month</span>\n        </div>\n\n        <div style={{ height: 5, borderRadius: 99, background: \"rgba(128,90,213,0.12)\", overflow: \"hidden\", marginBottom: 8 }}>\n          <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ duration: 0.8 }}\n            style={{ height: \"100%\", borderRadius: 99, background: isLow ? (pct <= 5 ? \"#EF4444\" : \"#F59E0B\") : \"#6B35E8\" }} />\n        </div>\n\n        {isLow && (\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 5, fontSize: 11, color: pct <= 5 ? \"#F87171\" : \"#FCD34D\" }}>\n            <AlertTriangle size={11} />\n            {pct <= 5 ? \"Almost out! Top up to keep KIRO running.\" : \"Running low on credits.\"}\n          </div>\n        )}\n      </div>\n\n      <AnimatePresence>\n        {showTopUp && <TopUpModal onClose={() => setShowTopUp(false)} />}\n      </AnimatePresence>\n    </>\n  );\n}\n"};
